+    const s = Math.sign(w.z);
+    w.z = s * (hw - 0.5); w.face = ppFaceZ(s);
+    w.x = k++ < nHead ? lerp(150, 325, r()) : lerp(-325, 150, r());   // headBias phần người đứng ở đoạn gần đầu rồng
+  });
